s_addc_u32 s[sgprKernArgAddress+1], s[sgprKernArgAddress+1], 0

/* Load Kernel Args */
s_mov_b64 s[32:33], s[6:7]                         // move preload data to correct sgpr
s_mov_b64 s[34:35], s[8:9]                         // move preload data to correct sgpr
s_mov_b64 s[36:37], s[10:11]                       // move preload data to correct sgpr
s_mov_b64 s[38:39], s[12:13]                       // move preload data to correct sgpr
s_mov_b64 s[40:41], s[14:15]                       // move preload data to correct sgpr
s_mov_b64 s[42:43], s[16:17]                       // move preload data to correct sgpr
s_mov_b64 s[44:45], s[18:19]                       // move preload data to correct sgpr
s_mov_b64 s[46:47], s[20:21]                       // move preload data to correct sgpr
s_mov_b64 s[48:49], s[22:23]                       // move preload data to correct sgpr
s_mov_b64 s[50:51], s[24:25]                       // move preload data to correct sgpr
s_mov_b64 s[52:53], s[26:27]                       // move preload data to correct sgpr
s_branch label_Preload_LoadArgsEnd
label_Preload_HBMArgs:
s_mov_b64 s[sgprKernArgAddress:sgprKernArgAddress+1], s[6:7] // Load address of kernel arguments
label_Preload_LoadArgsEnd:
s_mov_b32 s[sgprWGM], s4                           // Preload internal args2
s_mov_b32 s58, s5                                  // Load num of WGs
s_and_b32 s[sgprStaggerU], s57, 0xffff0000         // Restore StaggerU related vars
s_lshr_b32 s[sgprStaggerU], s[sgprStaggerU], 0x10
s_and_b32 s[sgprGSU], s57, 0xffff                  // Restore GSUConfig and GSU
s_mov_b32 s[sgprArgType], s56
s_mov_b32 m0, 0x38200                              // LDS clamp at 229888 bytes
s_set_vgpr_msb 64                                  // src0: 0, src1: 0, src2: 0, dst: 1
v_mov_b32 v[vgprSerial-256], v0                    // thread serial id
s_mov_b32 vcc_hi, 0                                // Ensure hi bits are zero
s_set_vgpr_msb 16384                               // src0: 0, src1: 0, src2: 0, dst: 0
v_readfirstlane_b32 s57, v0                        // first tId
s_lshr_b32 s[sgprWaveIdx], s57, 5                  // wId=fTid // wavelen
s_getreg_b32 s60, hwreg(28,6,4)                    // cluster_id
s_cmp_eq_u32 s60, 0                                // cluster_id == 0x0 ?
s_cbranch_scc0 label_EnableCluster
s_mov_b32 s[sgprWorkGroup0], ttmp9
s_and_b32 s[sgprWorkGroup1], 0xffff, ttmp7
s_lshr_b32 s[sgprWorkGroup2], ttmp7, 0x10
s_branch label_RemapWorkGroupDone
label_EnableCluster:
s_mov_b32 s60, ttmp6                               // Read TTMP6 register
s_mov_b32 s61, ttmp7                               // Read TTMP7 register,                                                                        cluster_z | cluster_y.
s_bfe_u32 s62, s60, 262148                         // Etract wg_y.
s_bfe_u32 s63, s60, 262160                         // Etract nwg_y. Value is nwg_y - 1
s_add_u32 s63, s63, 1
s_and_b32 s64, s61, 0xffff                         // Etract cluster_y.
s_mul_i32 s[sgprWorkGroup1], s64, s63              // cluster_y * nwg_y
s_add_u32 s[sgprWorkGroup1], s[sgprWorkGroup1], s62 // WorkGroup1 = (cluster_y * nwg_y) + wg_y
s_bfe_u32 s[sgprWorkGroup2], s61, 1048592          // Etract cluster_z.
s_and_b32 s61, s60, 0xf                            // Etract wg_x.
s_bfe_u32 s63, s60, 262156                         // Etract nwg_x. Value is nwg_x - 1
s_add_u32 s63, s63, 1
s_mul_i32 s[sgprWorkGroup0], ttmp9, s63            // cluster_x * nwg_x
s_add_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s61 // WorkGroup0 = (cluster_x * nwg_x) + wg_x
s_bfe_u32 s64, s60, 262152                         // Etract wg_z.
s_bfe_u32 s60, s60, 262164                         // Etract nwg_z. Value is nwg_z - 1
s_add_u32 s60, s60, 1
s_mul_i32 s[sgprWorkGroup2], s[sgprWorkGroup2], s60 // cluster_z * nwg_z
s_add_u32 s[sgprWorkGroup2], s[sgprWorkGroup2], s64 // WorkGroup2 = (cluster_z * nwg_z) + wg_z
label_RemapWorkGroupDone:
/* Calculate multicast mask */
/* reduce multicast mask to real WGs in cluster */
s_lshr_b32 s16, s[sgprSizeI], 7                    // s16 = s[sgprSizeI] / 128
s_and_b32 s66, 127, s[sgprSizeI]                   // s66 = s[sgprSizeI] % 128
s_addc_u32 s16, s16, 0
s_sub_u32 s60, s[sgprWorkGroup0], s61              // clusterBaseX
s_sub_u32 s16, s16, s60                            // tilesM - clusterBaseX
s_min_u32 s16, s16, 4                              // validX = min(.., cx)
s_bfm_b32 s64, s16, 0                              // maskRow bits = (1<<validX)-1
s_lshr_b32 s16, s[sgprSizeJ], 7                    // s16 = s[sgprSizeJ] / 128
s_and_b32 s66, 127, s[sgprSizeJ]                   // s66 = s[sgprSizeJ] % 128
s_addc_u32 s16, s16, 0
s_and_b32 s17, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s16, s16, s17                            // tilesN * GSU (raw y extent)
s_sub_u32 s60, s[sgprWorkGroup1], s62              // clusterBaseY
s_sub_u32 s16, s16, s60                            // tilesN*GSU - clusterBaseY
s_min_u32 s16, s16, 4                              // validY = min(.., cy)
s_mul_i32 s16, s16, 4                              // validY*cx
s_bfm_b32 s60, s16, 0                              // maskCol bits = (1<<(validY*cx))-1
s_bitcmp1_b32 s[sgprWaveIdx], 0                    // Check parity of wId
s_cbranch_scc1 label_setMulticastMask_OddWave      // Jump if wId is odd
label_setMulticastMask_EvenWave:
s_mov_b32 s[sgprMulticastMask], 0x1111             // Setting maskA for even wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], s60 // reduce to real WGs
s_lshl_b32 s[sgprMulticastMask], s[sgprMulticastMask], s61 // Setting maskA for even wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], 0xffff // keep workgroup_mask bits 15:0
s_branch label_setMulticastMaskEnd
label_setMulticastMask_OddWave:
s_mul_i32 s62, s62, s63                            // Shift factor: wg_y * nwg_x
s_mov_b32 s[sgprMulticastMask], 0xf                // Setting maskB for odd wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], s64 // reduce to real WGs
s_lshl_b32 s[sgprMulticastMask], s[sgprMulticastMask], s62 // Setting maskB for odd wave
s_and_b32 s[sgprMulticastMask], s[sgprMulticastMask], 0xffff // keep workgroup_mask bits 15:0
label_setMulticastMaskEnd:

/* remap workgroup to XCCs */
s_branch label_skip_WGMXCC
s_lshr_b32 s64, s[sgprWGM], 0x10                   // Get WGMXCC
s_ff1_i32_b32 s64, s64                             // Get log(WGMXCC)
s_lshr_b32 s65, s[sgprWGM], 0x16                   // Get CU_Count
/* remap WGs if WGMXCC > 1 ( log(WGMXCC) > 0 ) */
s_cmp_gt_i32 s64, 0
s_cbranch_scc0 label_skip_WGMXCC
/* only remap WGs in the range */
s_lshr_b32 s61, s58, s64
s_lshl_b32 s61, s61, s64
s_cmp_ge_u32 s[sgprWorkGroup0], s61
s_cbranch_scc1 label_skip_WGMXCC
s_cmp_eq_u32 s65, 0                                // CU_Count == 0 ?
s_cbranch_scc0 label_XCCG_nonzero
s_lshr_b32 s61, s[sgprWorkGroup0], s64
s_bfm_b32 s62, s64, 0
s_and_b32 s62, s[sgprWorkGroup0], s62
s_lshr_b32 s63, s58, s64
s_mul_i32 s62, s62, s63
s_add_u32 s[sgprWorkGroup0], s61, s62
s_branch label_skip_WGMXCC
label_XCCG_nonzero:
/* temp0 = (wg//CU_Count)*CU_Count */
s_nop 0
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f64_u32 v[0:1], s65                          // s61 = s[sgprWorkGroup0] / s65
v_rcp_f64 v[0:1], v[0:1]                           // s61 = s[sgprWorkGroup0] / s65
v_cvt_f64_u32 v[2:3], s[sgprWorkGroup0]            // s61 = s[sgprWorkGroup0] / s65
v_mul_f64 v[0:1], v[0:1], v[2:3]                   // s61 = s[sgprWorkGroup0] / s65
v_cvt_u32_f64 v0, v[0:1]                           // s61 = s[sgprWorkGroup0] / s65
v_mul_lo_u32 v1, v0, s65                           // s61 = s[sgprWorkGroup0] / s65
v_sub_nc_u32 v2, s[sgprWorkGroup0], v1             // s61 = s[sgprWorkGroup0] / s65
v_cmp_ge_u32 vcc_lo, v2, s65                       // s61 = s[sgprWorkGroup0] / s65
s_mov_b32 exec_lo, vcc_lo                          // s61 = s[sgprWorkGroup0] / s65
v_add_nc_u32 v0, v0, 1                             // s61 = s[sgprWorkGroup0] / s65
s_mov_b32 exec_lo, -1                              // Reset exec
v_mul_lo_u32 v1, v0, s65                           // s61 = s[sgprWorkGroup0] / s65
v_sub_nc_u32 v2, s[sgprWorkGroup0], v1             // s61 = s[sgprWorkGroup0] / s65
v_readfirstlane_b32 s61, v0                        // quotient
v_readfirstlane_b32 s62, v2                        // remainder
s_mul_i32 s61, s61, s65
/* temp1 = (wg%CU_Count)//WGMXCC */
s_lshr_b32 s62, s62, s64
/* temp0 = temp0 + temp1 */
s_add_u32 s61, s61, s62
/* temp1 = (wg%WGMXCC) * ((WGs - (WGs//CU_Count) * CU_Count) if (wg > (WGs//CU_Count) * CU_Count) else CU_Count)//WGMXCC */
v_cvt_f64_u32 v[0:1], s65                          // s62 = s58 / s65
v_rcp_f64 v[0:1], v[0:1]                           // s62 = s58 / s65
v_cvt_f64_u32 v[2:3], s58                          // s62 = s58 / s65
v_mul_f64 v[0:1], v[0:1], v[2:3]                   // s62 = s58 / s65
v_cvt_u32_f64 v0, v[0:1]                           // s62 = s58 / s65
v_mul_lo_u32 v1, v0, s65                           // s62 = s58 / s65
v_sub_nc_u32 v2, s58, v1                           // s62 = s58 / s65
v_cmp_ge_u32 vcc_lo, v2, s65                       // s62 = s58 / s65
s_mov_b32 exec_lo, vcc_lo                          // s62 = s58 / s65
v_add_nc_u32 v0, v0, 1                             // s62 = s58 / s65
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s62, v0                        // quotient
s_mul_i32 s62, s62, s65
s_sub_u32 s63, s58, s62
s_cmp_gt_u32 s[sgprWorkGroup0], s62
s_cselect_b32 s62, s63, s65
s_lshr_b32 s62, s62, s64
s_bfm_b32 s63, s64, 0
s_and_b32 s63, s[sgprWorkGroup0], s63
s_mul_i32 s62, s62, s63
/* WorkGroup0 = temp0 + temp1 */
s_add_u32 s[sgprWorkGroup0], s61, s62
label_skip_WGMXCC:  /// skip WGMXCC if no enough WGs to remap
s_cmp_eq_u32 s56, 3
s_cbranch_scc1 label_ArgType3_Routed_To_ArgType0
s_cmp_eq_u32 s56, 0
s_cbranch_scc0 label_MultiGemm
label_ArgType3_Routed_To_ArgType0:
/* init: add vgpr [130...390) to pool */
/* init: add vgpr [0...128) to pool */
/* init: add agpr [0...0) to pool */

/******************************************/
/* Local Read Addresses                   */
/******************************************/

/* local read addresses: tile assignments a/b */
/* lr0I */
s_nop 0
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_and_b32 v1, 31, v[vgprSerial-256]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v0, 15, v1                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v0, 7, v0                            // 1. N offset: nOffset = nIdx * nStride(128)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v0, 2, v0                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(4)
v_lshrrev_b32 v1, 4, v1                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v0, v1, 3, v0                       // 5. K offset: lrKOffset = kIdx * mStride(8); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-256]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v4, 1, v4                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshlrev_b32 v6, 16, v4                           // seg interleave: component byte offset = wtid0 * (fA+fB)
/* lr1J */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_and_b32 v2, 31, v[vgprSerial-256]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v1, 15, v2                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v1, 7, v1                            // 1. N offset: nOffset = nIdx * nStride(128)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v1, 2, v1                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(4)
v_lshrrev_b32 v2, 4, v2                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v1, v2, 3, v1                       // 5. K offset: lrKOffset = kIdx * mStride(8); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v3, 6, v[vgprSerial-256]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 1, v3                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshlrev_b32 v8, 16, v3                           // seg interleave: component byte offset = wtid0 * (fA+fB)

/* local read addresses: final offsets a */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v2, 5, v[vgprSerial-256]             // 2 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v2, 2, v2                            // LSU offset: Get LSU wave_id
s_mov_b32 s57, 128                                 // LSU offset: stride = lsuStride(128) when umlds==True
v_mul_lo_u32 v2, s57, v2                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
v_add_nc_u32 v[vgprLocalReadAddrA], v2, v0         // Final Offset: offset = (lro0+lsuoffset)*bpeDS
v_lshlrev_b32 v[vgprLocalReadAddrA], 1, v[vgprLocalReadAddrA] //  (multiple bpe)
v_lshrrev_b32 v3, 10, v[vgprLocalReadAddrA]        // Final Offset: padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalReadAddrA], v3, 4, v[vgprLocalReadAddrA] // Final Offset: padding 16 per block 1024
v_add_nc_u32 v[vgprLocalReadAddrA], v6, v[vgprLocalReadAddrA] // seg interleave: += wtid0*(fA+fB) (post-pad)

/* local read addresses: final offsets b */
s_set_vgpr_msb 4                                   // src0: 0, src1: 1, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-256]             // 0 = Serial / 32
s_set_vgpr_msb 1024                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
                                                   // LSU offset: stride = lsuStride(128) when umlds==True (dup assign opt.)
v_mul_lo_u32 v0, s57, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
v_add_nc_u32 v[vgprLocalReadAddrB], v0, v1         // Final Offset: offset = (lro1+lsuoffset)*bpeDS
v_lshlrev_b32 v[vgprLocalReadAddrB], 1, v[vgprLocalReadAddrB] //  (multiple bpe)
v_lshrrev_b32 v2, 10, v[vgprLocalReadAddrB]        // Final Offset: padding 16 per block 1024
v_lshl_add_u32 v[vgprLocalReadAddrB], v2, 4, v[vgprLocalReadAddrB] // Final Offset: padding 16 per block 1024
v_add_nc_u32 v[vgprLocalReadAddrB], v8, v[vgprLocalReadAddrB] // seg interleave: += wtid0*(fA+fB) (post-pad)

/* local read addresses: declare addresses a */

/* local read addresses: declare addresses b */
v_add_co_u32 v[vgprLocalReadAddrB+0], vcc_lo, 0x4100, v[vgprLocalReadAddrB+0] //  += LdsOffsetB (lower)

/******************************************/
/* Local Write Addresses                  */
/******************************************/

/* local write addresses: first offset a */

/* local write addresses: first offset b */
s_lshr_b32 s[sgprNumWorkGroups0], s[sgprSizesFree+0], 7 // s[sgprNumWorkGroups0] = s[sgprSizesFree+0] / 128
s_and_b32 s57, 127, s[sgprSizesFree+0]             // s57 = s[sgprSizesFree+0] % 128
s_cmp_gt_u32 s57, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups0], s[sgprNumWorkGroups0], 0 // Increment if remainder > 0
s_lshr_b32 s[sgprNumWorkGroups1], s[sgprSizesFree+1], 7 // s[sgprNumWorkGroups1] = s[sgprSizesFree+1] / 128
s_and_b32 s57, 127, s[sgprSizesFree+1]             // s57 = s[sgprSizesFree+1] % 128
s_cmp_gt_u32 s57, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups1], s[sgprNumWorkGroups1], 0 // Increment if remainder > 0
s_and_b32 s57, s[sgprArgType], 0xff                // mask ArgType domain (bits 8+ are internal flags)
s_cmp_eq_u32 s57, 2                                // ArgType == 2 ?
s_cbranch_scc0 label_SkipWaitForUserArgs           // skip wait if ArgType != 2
s_wait_kmcnt 0                                     // wait for 0/0 bytes of kern args
label_SkipWaitForUserArgs:  /// skip kern args wait if ArgType != 2

/* Early stop padded work-groups in a boundary cluster (grid rounded up to ClusterDim) */
s_cmp_ge_u32 s[sgprWorkGroup0], s[sgprNumWorkGroups0] // padded if WorkGroup0 >= tilesM
s_cbranch_scc1 label_ClusterPad_EarlyStop
s_and_b32 s56, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s56, s[sgprNumWorkGroups1], s56          // tilesN * GSU
s_cmp_ge_u32 s[sgprWorkGroup1], s56                // padded if WorkGroup1 >= tilesN*GSU
s_cbranch_scc1 label_ClusterPad_EarlyStop
s_branch label_ClusterPad_NoEarlyStop
label_ClusterPad_EarlyStop:
s_endpgm                                           // padded work-group: exit before any load/barrier
label_ClusterPad_NoEarlyStop:
s_branch label_MultiGemmEnd                        // Already using 3D WorkGroups, skip remap

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s56, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s57, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s56, s56, s57
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v0, s56                              // s56 = s[sgprWorkGroup0] / s56
v_rcp_iflag_f32 v0, v0                             // s56 = s[sgprWorkGroup0] / s56
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s56 = s[sgprWorkGroup0] / s56
v_mul_lo_u32 v1, v0, s56                           // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s56 = s[sgprWorkGroup0] / s56
v_mul_lo_u32 v1, v0, s56                           // s56 = s[sgprWorkGroup0] / s56
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s56 = s[sgprWorkGroup0] / s56
v_cmp_ge_u32 vcc_lo, v1, s56                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s56                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s56                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s56                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s56, v0                        // quotient
s_mov_b32 s[sgprWorkGroup2], s56
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s56, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_mul_i32 s56, s56, s[sgprWorkGroup2]
s_mul_i32 s56, s56, s57
